    "xpReward": 35,
    "orderIndex": 30,
    "estimatedMinutes": 18,
    "description": "ensayo de traducción: traducción y mediación.",
    "intro": "Lee para identificar el tema, las perspectivas, la evidencia y la conclusión.",
    "mission": "Reformular preservando intención y registro",
    "grammar": "",
    "phrases": [],
